// Generated by `just generate` from `src/plugins/claudetto/slices/turngate/lab/jobs.test.ts`. Edit the source and run `just generate`.
// Lab tests of the job check of the `turngate` slice: the `tool.check` of a `Bash` command.
// The tests give commands as strings, and no command runs.
// The file is self-contained, because `just generate` copies it to `tests/` of the plugin, where it cannot import a relative file.

import type { On } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

/** Stubs for the hooks of other slices on the same calls. */
const setup = (on: On) => {
  mock.env(on, { HOME: "/home/u" });
  on("fs.exists", () => ({ value: false }));
  on("tool.check", () => ({ decision: "allow" as const }));
};

const bash = ($: Engine, command: string) =>
  $.tool.check({ tool: "Bash", input: { command } });

test("a job of a lone `&` with no `wait` is denied", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "sleep 30 &");
  expect(out?.decision).toBe("deny");
});

test("a job that `wait` ends passes", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "sleep 1 & sleep 2 & wait");
  expect(out?.decision).not.toBe("deny");
});

test("a `nohup` job is denied", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "nohup sleep 30 > /dev/null 2>&1");
  expect(out?.decision).toBe("deny");
});

test("a `setsid` job behind a wrapper is denied", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "timeout 5 setsid sleep 30");
  expect(out?.decision).toBe("deny");
});

test("a stop by `pkill` or by `kill` with `pgrep` is denied", async ($: Engine, on: On) => {
  setup(on);
  expect((await bash($, "pkill -f vite"))?.decision).toBe("deny");
  expect((await bash($, "kill $(pgrep -f vite)"))?.decision).toBe("deny");
});

test("a `kill` by PID passes", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "kill 4242");
  expect(out?.decision).not.toBe("deny");
});

test("`&&` and `2>&1` start no job", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "echo a && echo b 2>&1");
  expect(out?.decision).not.toBe("deny");
});

test("the deny reason names `run_in_background` and the PID", async ($: Engine, on: On) => {
  setup(on);
  const out = await bash($, "sleep 30 &");
  const reason = out?.decision === "deny" ? out.reason : "";
  expect(reason).toContain("`run_in_background: true`");
  expect(reason).toContain("PID");
  expect(reason).toContain("a job of a lone `&` with no `wait`");
});
